"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["61948"],{93897(e){e.exports=JSON.parse('{"id":"F266","slug":"margin-return","name":"Return on a Margin Purchase","subject":"Equity Markets","section":"Equities","topic":"Margin trading","level":"Intermediate","aliases":["buying on margin","leverage return","margin loan","levered equity return"],"formula":{"latex":"R_{equity}=\\\\frac{Q\\\\,(P_{1}-P_{0})-L\\\\,i\\\\,t}{E},\\\\quad L=Q\\\\,P_{0}-E","also":[],"text":"Return on equity = (Shares x Price change - Loan x Interest rate x Years) / Your own money; Loan = Shares x Start price - Your own money"},"symbols":[{"symbol":"E","meaning":"Your own money put in","unit":"money"},{"symbol":"L","meaning":"Amount borrowed from the broker","unit":"money"},{"symbol":"Q","meaning":"Shares bought, total purchase divided by the start price","unit":"number"},{"symbol":"P_0, P_1","meaning":"Price at the start and at the end","unit":"money"},{"symbol":"i","meaning":"Interest rate on the margin loan","unit":"per year"},{"symbol":"t","meaning":"Years held","unit":"years"}],"when_to_use":"Use it to see how borrowing magnifies results. A gain is multiplied by the leverage, and so is a loss, and the interest cost is charged either way.","worked_example":{"problem":"You have 10,000 and buy shares at 50 with an initial margin of 50%, so total buying is 20,000. The price rises to 60 after one year. The margin loan costs 6%. What is your return, compared with buying without a loan?","inputs":{"e":10000,"m":50,"p0":50,"p1":60,"i":6,"t":1},"steps":[{"label":"Total purchase = own money / margin","working":"10000 / 0.5","value":"20,000.00"},{"label":"Loan = total purchase - own money","working":"20000-10000","value":"10,000.00"},{"label":"Shares = purchase / start price","working":"20000 / 50","value":"400.0"},{"label":"Interest = loan x rate x years","working":"10000 x 0.06 x 1","value":"600.00"},{"label":"Ending equity = shares x end price - loan - interest","working":"400 x 60-10000-600","value":"13,400.00"},{"label":"Return on own money = (equity - own money) / own money","working":"(13400-10000) / 10000","value":"34.00%"},{"label":"Return without a loan = p1 / p0 - 1","working":"60 / 50-1","value":"20.00%"}],"answer":"You bought 400.0 shares with a loan of 10,000.00. After interest of 600.00 your equity grows to 13,400.00, a return of 34.00%. Without borrowing the same price rise gives 20.00%. A fall of the same size would hurt by the same multiple."},"calculator":{"available":true,"inputs":[{"id":"e","label":"Your own money","unit":"money","type":"number","default":10000,"hint":""},{"id":"m","label":"Initial margin","unit":"%","type":"number","default":50,"hint":""},{"id":"p0","label":"Start price","unit":"money","type":"number","default":50,"hint":""},{"id":"p1","label":"End price","unit":"money","type":"number","default":60,"hint":""},{"id":"i","label":"Margin loan interest rate","unit":"%","type":"number","default":6,"hint":""},{"id":"t","label":"Years held","unit":"years","type":"number","default":1,"hint":""}],"checks":[{"expr":"m>0 and m<=1","message":"The initial margin must be above 0% and no more than 100%."}],"steps":[{"id":"buy","label":"Total purchase = own money / margin","expr":"e/m","format":"money"},{"id":"loan","label":"Loan = total purchase - own money","expr":"buy-e","format":"money"},{"id":"q","label":"Shares = purchase / start price","expr":"buy/p0","format":"num1"},{"id":"int_","label":"Interest = loan x rate x years","expr":"loan*i*t","format":"money"},{"id":"eq","label":"Ending equity = shares x end price - loan - interest","expr":"q*p1-loan-int_","format":"money"},{"id":"ret","label":"Return on own money = (equity - own money) / own money","expr":"(eq-e)/e","format":"pct2"},{"id":"plain","label":"Return without a loan = p1 / p0 - 1","expr":"p1/p0-1","format":"pct2"}],"results":["ret","plain"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"q":400,"eq":13400,"ret":0.34,"plain":0.2}},"finder":{"finds":"How borrowing magnifies a return","needs":"Own money, margin, prices, loan rate, years"},"related":[{"slug":"margin-call-price","name":"Margin Call Price"},{"slug":"short-sale-return","name":"Short Sale Profit and Return"},{"slug":"wacc","name":"Weighted Average Cost of Capital (WACC)"}],"related_ids":["F265","F263","F165"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msub><mi>R</mi><mrow><mi>e</mi><mi>q</mi><mi>u</mi><mi>i</mi><mi>t</mi><mi>y</mi></mrow></msub><mo>=</mo><mfrac><mrow><mi>Q</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mn>1</mn></msub><mo>\u2212</mo><msub><mi>P</mi><mn>0</mn></msub><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mi>L</mi><mtext>\u2009</mtext><mi>i</mi><mtext>\u2009</mtext><mi>t</mi></mrow><mi>E</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>L</mi><mo>=</mo><mi>Q</mi><mtext>\u2009</mtext><msub><mi>P</mi><mn>0</mn></msub><mo>\u2212</mo><mi>E</mi></mrow><annotation encoding=\\"application/x-tex\\">R_{equity}=\\\\frac{Q\\\\,(P_{1}-P_{0})-L\\\\,i\\\\,t}{E},\\\\quad L=Q\\\\,P_{0}-E</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"retirement-nest-egg","name":"Retirement Nest Egg and Required Saving"},"next":{"slug":"return-on-assets","name":"Return on Assets (ROA)"},"lesson":null,"total":522}')}}]);